import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"从 EssentialsX Kits 迁移","description":"","frontmatter":{},"headers":[],"relativePath":"modules/kits/migration-essentialsx.md","filePath":"modules/kits/migration-essentialsx.md","lastUpdated":0}`),a={name:`modules/kits/migration-essentialsx.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="从-essentialsx-kits-迁移" tabindex="-1">从 EssentialsX Kits 迁移 <a class="header-anchor" href="#从-essentialsx-kits-迁移" aria-label="Permalink to “从 EssentialsX Kits 迁移”">​</a></h1><p>本页给把 EssentialsX 的 kits 功能迁到 EmakiKits 的服主. 对照只写有据可依的部分 (依据 EssentialsX 官网与 GitHub README), 不确定处标注「待确认」</p><h2 id="概念映射" tabindex="-1">概念映射 <a class="header-anchor" href="#概念映射" aria-label="Permalink to “概念映射”">​</a></h2><table tabindex="0"><thead><tr><th>EssentialsX</th><th>EmakiKits</th><th>说明</th></tr></thead><tbody><tr><td><code>kits.yml</code> 里的一个 kit</td><td><code>kits/*.yml</code> 里的一个礼包</td><td>EmakiKits 一文件一礼包, id 取文件内 <code>id</code> 字段, 与文件名无关</td></tr><tr><td>kit 物品列表</td><td><code>rewards.fixed</code></td><td>EmakiKits 奖励写 CoreLib 物品来源简写 (<code>minecraft-bread</code> 等), 与 EssentialsX 的物品写法不同, 需人工转写</td></tr><tr><td><code>delay</code> (秒) 冷却</td><td>周期礼包 / <code>max_claims_total</code></td><td>EssentialsX 是秒级冷却; EmakiKits 用 <code>daily</code> / <code>weekly</code> / <code>monthly</code> 周期键或累计上限近似, 秒级冷却不支持 (待确认)</td></tr><tr><td><code>delay: -1</code> 一次性</td><td><code>max_claims_total: 1</code></td><td>一次性礼包的等价写法</td></tr><tr><td>kit 权限</td><td>礼包 <code>permission</code> 字段</td><td>EssentialsX 用 <code>essentials.kit.&lt;名称&gt;</code> 形态 (以 EssentialsX 文档为准); EmakiKits 要求权限以 <code>emakikits.</code> 开头, 迁移时需改节点并同步 LuckPerms</td></tr></tbody></table><p>EssentialsX 没有 CDK, 自选, 邀新与周期礼包概念 (取证范围未见, 不等于确认没有); 迁移后这些能力是净新增</p><h2 id="命令映射" tabindex="-1">命令映射 <a class="header-anchor" href="#命令映射" aria-label="Permalink to “命令映射”">​</a></h2><table tabindex="0"><thead><tr><th>EssentialsX</th><th>EmakiKits</th></tr></thead><tbody><tr><td><code>/kit &lt;名称&gt;</code></td><td><code>/ekits claim &lt;礼包ID&gt;</code></td></tr><tr><td><code>/kit list</code></td><td><code>/ekits list</code></td></tr><tr><td>(无)</td><td><code>/ekits preview &lt;礼包ID&gt;</code> 领取前预览</td></tr><tr><td>(无)</td><td><code>/ekits redeem &lt;礼包ID&gt; &lt;兑换码&gt;</code> CDK 兑换</td></tr></tbody></table><h2 id="数据迁移" tabindex="-1">数据迁移 <a class="header-anchor" href="#数据迁移" aria-label="Permalink to “数据迁移”">​</a></h2><ul><li>EmakiKits 的礼包定义是 <code>plugins/EmakiKits/kits/*.yml</code>, 运行数据是 <code>plugins/EmakiKits/data/store.yml</code>, 与 EssentialsX 的 <code>kits.yml</code> / userdata 互不相通</li><li><strong>没有自动导入</strong>: 礼包定义按上表人工改写; EssentialsX 记录的玩家领取冷却数据无法导入, 迁移后 EmakiKits 从空记录开始 (如需保留&quot;已领过&quot;状态, 无工具支持, 待确认)</li></ul><h2 id="迁移步骤建议" tabindex="-1">迁移步骤建议 <a class="header-anchor" href="#迁移步骤建议" aria-label="Permalink to “迁移步骤建议”">​</a></h2><ol><li>测试服安装 EmakiCoreLib + EmakiKits, 把 <code>kits.yml</code> 逐个改写成 <code>kits/*.yml</code> (对照概念映射表)</li><li><code>/ekits check</code> 确认加载状态, <code>/ekits preview</code> 核对奖励内容</li><li>切换权限节点 (LuckPerms 里把 <code>essentials.kit.*</code> 换成对应 <code>emakikits.*</code> 节点), 验证领取</li><li>确认无误后再停用 EssentialsX 的 kits 用法 (EssentialsX 其他功能不受影响)</li></ol>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};